import type { GamesApi } from "../../api";
import { legalMoves, play, playSan, toSan } from "../../lib/chess/chess";
import { decode } from "./codec";
import type { OpeningItem, OpeningsDataFile, OpeningsDataset } from "./types";
// generated by `bun run src/cli.ts data openings`; text, so it is parsed as JSON rather than as code
import raw from "./data.json" with { type: "text" };

/** Pools offered for the openings dataset; the first is the default. */
export const POOLS = [
  { label: "every named line", query: "" },
  { label: "openings, not variations", query: "!variation" },
  { label: "up to 10 plies", query: "plies<=10" },
  { label: "1. e4", query: "first:e4" },
  { label: "1. d4", query: "first:d4" },
  { label: "flank openings (A)", query: "volume:A" },
  { label: "semi-open games (B)", query: "volume:B" },
  { label: "open games and the French (C)", query: "volume:C" },
  { label: "closed and semi-closed games (D)", query: "volume:D" },
  { label: "Indian defenses (E)", query: "volume:E" },
] as const;

/** Named chess openings, each with its moves from the start, for any pack to build games on. */
export default function pack(games: GamesApi): void {
  const file = JSON.parse(raw as unknown as string) as OpeningsDataFile;
  let items: OpeningItem[] | null = null;
  const dataset: OpeningsDataset = {
    id: "openings",
    name: "chess openings",
    version: file.version,
    credits: file.credits,
    attributes: file.attributes,
    noun: { one: "opening", many: "openings" },
    featured: ["eco", "family", "first", "plies"],
    pools: POOLS,
    spelling: {
      label: "moves",
      primary: true,
      of: (it) => it.moves,
      // any legal line is a fair guess, written exactly as SAN writes it (Nxf7+, not Nxf7)
      valid: (seq) => {
        try {
          const { moves } = playSan(seq);
          let p = playSan([]).position;
          for (const [i, m] of moves.entries()) {
            const san = toSan(p, m);
            if (san !== seq[i]) return `move ${i + 1} is written ${san}`;
            p = play(p, m);
          }
          return null;
        } catch {
          const ok = (() => { try { playSan(seq.slice(0, -1)); return true; } catch { return false; } })();
          return ok ? `${seq[seq.length - 1]} isn't a legal move there` : "not a legal line of moves";
        }
      },
      next: (prefix) => {
        try {
          const p = playSan(prefix).position;
          return legalMoves(p).map((m) => toSan(p, m));
        } catch {
          return [];
        }
      },
    },
    items: () => (items ??= decode(file)),
  };
  games.registry.dataset(dataset);
}
